import json, hashlib
from pathlib import Path
from datetime import datetime
for name in ('regras.md', 'eventos.json'):
    print(name, hashlib.sha256(Path(name).read_bytes()).hexdigest())
events = json.loads(Path('eventos.json').read_text())
unique = {}
retries = []
for event in events:
    key = event['event_id']
    if key in unique:
        assert event == unique[key], f'Duplicata conflitante: {key}'
        retries.append(key)
    else:
        unique[key] = event
start = datetime.fromisoformat('2026-10-10T00:00:00+00:00')
end = datetime.fromisoformat('2026-10-11T00:00:00+00:00')
time = lambda event: datetime.fromisoformat(event['em'].replace('Z', '+00:00'))
payments = [e for e in unique.values() if e['tipo'] == 'pago' and e['moeda'] == 'BRL' and start <= time(e) < end]
orders = {e['pedido'] for e in payments}
refunds = [e for e in unique.values() if e['tipo'] == 'estorno_confirmado' and e['pedido'] in orders and time(e) < end]
channels = {'loja': 0, 'web': 0}
for payment in payments:
    gross = payment['valor']
    deducted = sum(e['valor'] for e in refunds if e['pedido'] == payment['pedido'])
    channels[payment['canal']] += gross - deducted
    print(json.dumps({'pedido': payment['pedido'], 'pagamento': payment['event_id'], 'canal': payment['canal'], 'bruto': gross, 'estornos': deducted, 'liquido': gross - deducted}, ensure_ascii=False))
print(json.dumps({'eventos_lidos': len(events), 'eventos_unicos': len(unique), 'retries': retries, 'estornos_aceitos': [e['event_id'] for e in refunds], 'resultado': {'pedidos_incluidos': sorted(orders), 'receita_liquida_centavos': sum(channels.values()), 'por_canal_centavos': channels}}, ensure_ascii=False))
PY"

